import sys

words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
order = {w: i for i, w in enumerate(words)}

data = sys.stdin.read().strip()
if not data:
    print('')
else:
    tokens = data.split()
    tokens.sort(key=lambda w: order[w])
    print(' '.join(tokens))

import sys

s = sys.stdin.read()
tokens = s.split()
depths = []

for t in tokens:
    depth = 0
    max_depth = 0
    for ch in t:
        if ch == '(':
            depth += 1
            if depth > max_depth:
                max_depth = depth
        elif ch == ')':
            depth -= 1
    depths.append(max_depth)

print(depths)

